 IEnumerator ParkingFull(){yield return SportsProbeScene.Ensure<ParkingMatch>("TruckMusicalParking");var m=FindAnyObjectByType<ParkingMatch>();yield return null;for(int seed=0;seed<3;seed++){m.AllBots();UnityEngine.Random.InitState(2139+seed*139);m.StartMatch();Time.timeScale=4;var prior=new Vector3[8];var idle=new float[8];float next=Time.time+1,until=Time.realtimeSinceStartup+180;int round=0;while(!m.Finished&&Time.realtimeSinceStartup<until){if(round!=m.Round){round=m.Round;Array.Clear(idle,0,8);log.AppendLine("ROUND seed="+seed+" round="+round+" remaining="+m.Remaining);}if(Time.time>=next){float dt=1;next=Time.time+1;int open=0;foreach(var b in m.bays)if(b.gameObject.activeSelf&&b.Owner<0)open++;var target=(int[])Field(typeof(ParkingMatch),"selected").GetValue(m);for(int i=0;i<8;i++){var t=m.trucks[i];bool stuck=m.Phase==ParkingPhase.Scramble&&m.active[i]&&m.secured[i]<0&&m.penalty[i]<=0&&open>0&&(t.body.position-prior[i]).sqrMagnitude<.25f;idle[i]=stuck?idle[i]+dt:0;prior[i]=t.body.position;if(idle[i]>=3){log.AppendLine("STALL seed="+seed+" round="+round+" slot="+i+" age="+m.Age+" idle="+idle[i]+" position="+t.body.position+" speed="+t.body.linearVelocity.magnitude+" drive="+t.command+" target="+target[i]+" open="+open+" eligibility="+m.Eligibility(i));File.WriteAllText(folder+"/stall.txt",log.ToString());}}File.WriteAllText(folder+"/progress.txt",log.ToString());}yield return null;}Check(m.Finished,"autonomous seeded full match completes seed="+seed+" rounds="+m.Round+" captures="+m.TotalCaptures);m.SetupScreen();Time.timeScale=1;}}
 IEnumerator Parking(){yield return SportsProbeScene.Ensure<ParkingMatch>("TruckMusicalParking");var m=FindAnyObjectByType<ParkingMatch>();yield return null;m.AllBots();UnityEngine.Random.InitState(31719);Check(m.StartMatch(),"eight AI contenders start");Time.timeScale=3;while(m.Phase==ParkingPhase.Countdown)yield return null;m.Horn();for(int i=0;i<8;i++){m.penalty[i]=0;m.returned[i]=true;}var selected=(int[])Field(typeof(ParkingMatch),"selected").GetValue(m);var reactions=(float[])Field(typeof(ParkingMatch),"reaction").GetValue(m);Array.Clear(reactions,0,8);selected[0]=0;for(int i=1;i<=6;i++){var b=m.bays[i-1];m.trucks[i].Prepare(b.transform.position+Vector3.up*.55f,b.transform.rotation);Check(m.Secure(i,i-1),"single owner fixture bay="+(i-1));}Check(selected[0]<0&&!m.Secure(0,0)&&!m.Secure(1,6),"claimed target invalidates immediately; duplicate bay and multiple bay ownership rejected");m.trucks[7].Park(new Vector3(38,.55f,27));var t=m.trucks[0];var start=m.bays[0].transform.position+new Vector3(0,.55f,-4.5f);t.Prepare(start,Quaternion.identity);selected[0]=0;Physics.SyncTransforms();float until=Time.time+20;float moved=0,driving=0;while(m.Phase==ParkingPhase.Scramble&&m.secured[0]<0&&Time.time<until){moved=Mathf.Max(moved,Vector3.Distance(start,t.body.position));if(Mathf.Abs(t.command.y)>.1f)driving+=Time.deltaTime;yield return null;}log.AppendLine("MEASURE subject="+t.body.position+" target="+selected[0]+" moved="+moved+" driving="+driving+" secured="+m.secured[0]+" phase="+m.Phase+" open6="+m.bays[6].Open);Check(m.secured[0]==6,"occupied-bay physical escape drives to and captures sole available bay within twenty seconds");m.SetupScreen();Time.timeScale=1;}
 IEnumerator Poker(){yield return SportsProbeScene.Ensure<PokerMatch>("TruckPoker");var m=FindAnyObjectByType<PokerMatch>();yield return null;m.setup.count=4;m.NormalizeSetup();m.AllBots();Check(m.StartMatch(),"real Poker table starts");yield return null;var card=m.presentation.spectatorBoard[0];m.enabled=false;foreach(var pane in m.presentation.panes)pane.root.gameObject.SetActive(false);m.presentation.spectatorRoot.SetActive(true);for(int c=0;c<52;c++){card.Clear(true);card.Show(c);Canvas.ForceUpdateCanvases();card.rank.ForceMeshUpdate(true,true);int rank=PokerHand.Rank(c);string expected=rank==14?"A":rank==13?"K":rank==12?"Q":rank==11?"J":rank.ToString();Check(card.rank.text==expected&&card.rank.textInfo.characterCount==expected.Length&&card.rank.textInfo.meshInfo[0].vertexCount>=expected.Length*4,"real rank/suit renderer card="+c+" expected="+expected+" actual="+card.rank.text+" vertices="+card.rank.textInfo.meshInfo[0].vertexCount);yield return null;}
