public sealed class SportsRepairContactObserver:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 public LWS.TruckBungeeDemolition.BungeeBay bay;public int contacts;public readonly StringBuilder record=new StringBuilder();Vector3 incoming;
 void FixedUpdate(){if(bay!=null)incoming=bay.truck.body.linearVelocity;}
 void OnCollisionEnter(Collision c){if(bay==null||!bay.AcceptScore)return;contacts++;var mod=c.collider.GetComponent<LWS.TruckBungeeDemolition.BungeeModule>();float speed=0;for(int i=0;i<c.contactCount;i++)speed=Mathf.Max(speed,Mathf.Max(0,-Vector3.Dot(incoming,c.GetContact(i).normal)));record.AppendLine("CONTACT time="+Time.time+" object="+c.collider.name+" incomingNormal="+speed+" relative="+c.relativeVelocity+" hp="+(mod!=null?mod.core.HealthRatio:-1)+" collapsed="+(mod!=null&&mod.core.HasCollapsed)+" kinematic="+(c.rigidbody!=null&&c.rigidbody.isKinematic));}
#endif
}
